"""Helper function to determine which font color to use"""
def font_color_helper(
    background_color: Any, light_color: Any = None, dark_color: Any = None
) -> object {
    light_color = light_color if (light_color is not None) else "#FFFFFF";
    dark_color = dark_color if (dark_color is not None) else "#000000";
    tmp_color = background_color.strip().strip('#');
    tmp_r = int(tmp_color[:2], 16);
    tmp_g = int(tmp_color[2:4], 16);
    tmp_b = int(tmp_color[4:], 16);
    font_color_code = dark_color
        if (((tmp_r * 0.299) + (tmp_g * 0.587) + (tmp_b * 0.114)) > 186)
        else light_color;
    return font_color_code;
}

"""
    >>> num2int('1,000,000')
    1000000
    """
def num2int(num: Any) -> object {
    return int(num.replace(',', ''));
}

"""
    This function removes from the entire set hostnames found, the ones who
    do not end with the target provided domain name.
    So if in the list of domains we have example.com and our target/scope
    is example.it, then example.com will be removed because falls out of the
    scope.

    Args:
    domains -- the list of input target domains

    Returns:
    subdomains -- the set of subomains strictly respecting the scope
    """
def remove_unrelated_domains(subdomains: Any, domains: Any) -> object {
    subdomains = [
        s
        for s in subdomains
        if s.endswith(`tuple(domains))
    ];
    return subdomains;
}

