      Args:
         payload: String
            SQL query
         lst: List of Strings
            keywords for payload dictionary

      Returns:
         dikt: dictionary
            dictionary using elements of lst as keys and payload as value for each key
   """
def payloadDictionary(payload: Any, lst: Any) -> object {
    dikt = {};
    for i in lst {
        dikt[i] = payload;
    }
    return dikt;
}

"""Utility function used by getterName and setterName."""
def _buildGetterOrSetter(prefix: Any, varName: Any) -> object {
    if (varName[0] == '_') {
        varName = varName[1:];
    }
    return (prefix + varName[0].upper() + varName[1:]);
}

